import type { Meta, StoryObj } from "@storybook/vue3";
import { Stars01 } from "@kozmos-ds/icons/vue";
import { h } from "vue";
import { KozmosButton, KozmosNotice } from "../../index";

/**
 * Vue's Notice: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story and React's decorator's box. test/parity draws each of React's in both
 * and holds Vue's render to React's: its args stories in
 * stories.parity.spec.ts, the rest in notice.parity.spec.ts. Generated by
 * `port Notice`; Emergency, SearchWithAi and SuccessProgressAndDone written
 * by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["summary", "children", "icon", "action"];

const meta: Meta<Args> = {
  title: "Vue/Core/Feedback/Notice",
  component: KozmosNotice,
  parameters: { layout: "centered" },
  // React's decorator, as React draws it: its w-[22rem] is not in React's
  // stylesheet, so the box takes no width there, nor here.
  decorators: [() => ({ template: `<div class="w-[22rem]"><story /></div>` })],
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosNotice, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

/**
 * Story 14's dietary notice. One line above the results, with the full legal
 * wording a tap away.
 */
export const Collapsed: Story = {
  args: {
    summary: "AI results may be incomplete. Check allergens with the venue.",
    children:
      "These results are AI-assisted and may be incomplete or out of date. If you have an allergy or intolerance, confirm with the venue or its staff before you order.",
  },
};

export const Expanded: Story = {
  args: { ...Collapsed.args, defaultExpanded: true },
};

/**
 * Help first, not a result list. Nothing is hidden and the way to act is
 * already on screen: nobody in an emergency should have to find a "More" link.
 */
export const Emergency: Story = {
  render: () => ({
    components: { KozmosButton, KozmosNotice },
    template: `
      <KozmosNotice tone="critical" :collapsible="false">
        <template #summary>If someone's life is in danger, call 112 now</template>
        Airport staff can help too. The nearest help points are below.
        <template #action>
          <KozmosButton variant="destructive">Call 112</KozmosButton>
        </template>
      </KozmosNotice>
    `,
  }),
};

/** No detail, so no disclosure is offered. */
export const SingleLine: Story = {
  args: {
    tone: "info",
    summary: "Results are generated by AI and may contain mistakes.",
  },
};

/**
 * MAP-474's Search with AI suggestion: one line holding a control, so the
 * icon centres on it rather than sitting on its first line of text
 * (GAP-118). The product's own mark replaces the tone's.
 */
export const SearchWithAi: Story = {
  render: () => ({
    components: { KozmosButton, KozmosNotice, Stars01 },
    template: `
      <KozmosNotice tone="info" icon-align="center">
        <template #icon><Stars01 class="h-4 w-4" /></template>
        <template #summary>
          <span class="flex items-center justify-between gap-2">
            Not finding it?
            <KozmosButton size="sm" variant="outline">Search with AI</KozmosButton>
          </span>
        </template>
      </KozmosNotice>
    `,
  }),
};

/**
 * GAP-160: the building editor's geometry notices. A warning with its
 * action under the words, the save in progress with the loading arc where
 * the mark is, and done, which ends in a check at the inline end.
 */
export const SuccessProgressAndDone: Story = {
  render: () => ({
    components: { KozmosButton, KozmosNotice },
    template: `
      <div class="flex flex-col gap-3">
        <KozmosNotice tone="warning" :collapsible="false">
          <template #summary>Set Geometry</template>
          Draw the building's outline on the map.
          <template #action>
            <KozmosButton size="sm" variant="outline">Set Building Boundary</KozmosButton>
          </template>
        </KozmosNotice>
        <KozmosNotice tone="info" status="progress">
          <template #summary>Saving the geometry</template>
        </KozmosNotice>
        <KozmosNotice tone="success" status="done">
          <template #summary>Geometry is set</template>
        </KozmosNotice>
      </div>
    `,
  }),
};

/** The success tone, with its own mark: Toast's check. */
export const Success: Story = {
  args: {
    tone: "success",
    summary: "Your changes are published.",
  },
};
